val g = RunnableGraph.fromGraph(GraphDSL.create() { implicit b =>
  val p = b.add(Partition[Message](2, {
    case _: OrderCreated  => 0
    case _: InvoiceIssued => 1
  }))
  source ~> p.in
  p.out(0) ~> ordersSink      // each element reaches exactly one outlet
  p.out(1) ~> invoicesSink
  ClosedShape
})
